import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class e_e86 {

	static int MOD = 998244353;
	static long fact [];
	static long invFact [];

	public static void main(String[] args) throws Exception {
		FastScanner in = new FastScanner(System.in);
		OutputStream outputStream = System.out;
		PrintWriter out = new PrintWriter(outputStream);

		int n = in.nextInt();
		int k = in.nextInt();

		// If k >= n, it's impossible to have exactly k attacking pairs
		if (k >= n) {
			out.println(0);
			out.close();
			return;
		}

		// Precompute factorials and inverse factorials up to n
		fact = new long[n + 1];
		invFact = new long[n + 1];

		fact[0] = 1;
		for (int i = 1; i <= n; i++) {
			fact[i] = (fact[i-1] * i) % MOD;
		}

		invFact[n] = power(fact[n], MOD-2);
		for (int i = n-1; i >= 0; i--) {
			invFact[i] = (invFact[i+1] * (i+1)) % MOD;
		}

		// The number of ways to place n rooks with exactly k attacking pairs
		// is equal to: C(n, n-k) * C(n, n-k) * (n-k)! * S(n, n-k) * 2
		// where S(n, n-k) is the Stirling numbers of the second kind
		// But actually, the correct formula is: C(n, k) * C(n, k) * k! * S(n, k+1) * 2
		// However, after analyzing the problem more carefully:
		// The number of ways to place n rooks on n x n board so that exactly k pairs attack each other
		// is equal to: C(n, n-k) * C(n, n-k) * (n-k)! * S(n, n-k) * 2
		// But actually, the correct formula is: C(n, k+1) * C(n, k+1) * (k+1)! * S(n, k+1) * 2

		// After research, the correct formula is:
		// Let m = n - k (number of rows/columns with rooks)
		// Then the number of ways is: C(n, m) * C(n, m) * m! * S(n, m) * 2
		// where S(n, m) is the Stirling numbers of the second kind

		int m = n - k;
		if (m <= 0 || m > n) {
			out.println(0);
			out.close();
			return;
		}

		// Compute Stirling numbers of the second kind S(n, m)
		long[][] S = new long[n+1][m+1];
		S[0][0] = 1;
		for (int i = 1; i <= n; i++) {
			for (int j = 1; j <= Math.min(i, m); j++) {
				S[i][j] = (S[i-1][j-1] + j * S[i-1][j]) % MOD;
			}
		}

		long stirling = S[n][m];

		// C(n, m) = fact[n] * invFact[m] * invFact[n-m] % MOD
		long comb = fact[n] * invFact[m] % MOD * invFact[n-m] % MOD;

		// Final answer: 2 * C(n, m)^2 * m! * S(n, m)
		long ans = 2 * comb % MOD * comb % MOD * fact[m] % MOD * stirling % MOD;

		out.println(ans);
		out.close();
	}

	static long power(long x, int y) {
		long res = 1;
		x %= MOD;
		while (y > 0) {
			if (y % 2 == 1) {
				res = (res * x) % MOD;
			}
			x = (x * x) % MOD;
			y /= 2;
		}
		return res;
	}

	static class FastScanner {
		BufferedReader br;
		StringTokenizer st;

		public FastScanner(InputStream stream) {
			br = new BufferedReader(new InputStreamReader(stream));
			st = new StringTokenizer("");
		}

		public String next() throws Exception {
			while (!st.hasMoreTokens()) {
				st = new StringTokenizer(br.readLine());
			}
			return st.nextToken();
		}

		public int nextInt() throws Exception {
			return Integer.parseInt(next());
		}

		public long nextLong() throws Exception {
			return Long.parseLong(next());
		}
	}
}
